    51	    private static boolean isValid(String address) {
    52	        if (address == null) {
    53	            return false;
    54	        }
    55	        int at = address.indexOf('@');
    56	        if (at < 1 || at != address.lastIndexOf('@')) {
    57	            return false;
    58	        }
    59	        String domain = address.substring(at + 1);
    60	        int dot = domain.indexOf('.');
    61	        return dot > 0 && domain.lastIndexOf('.') < domain.length() - 1 && !domain.endsWith(".");
    62	    }
